  const SystemAudio({required this.inputs, required this.outputs});

  @override
  int get hashCode => inputs.hashCode ^ outputs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SystemAudio &&
          runtimeType == other.runtimeType &&
          inputs == other.inputs &&
          outputs == other.outputs;
}

/// One voicemail message.
class Voicemail {
  final String id;
  final String caller;
  final String? callerName;
  final bool new_;
  final bool urgent;
  final BigInt durationSecs;
  final String? transcription;

  /// RFC 3339.
  final String receivedAt;

  const Voicemail({
    required this.id,
    required this.caller,
    this.callerName,
    required this.new_,
    required this.urgent,
    required this.durationSecs,
    this.transcription,
    required this.receivedAt,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      caller.hashCode ^
      callerName.hashCode ^
      new_.hashCode ^
      urgent.hashCode ^
      durationSecs.hashCode ^
      transcription.hashCode ^
      receivedAt.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Voicemail &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          caller == other.caller &&
          callerName == other.callerName &&
          new_ == other.new_ &&
          urgent == other.urgent &&
          durationSecs == other.durationSecs &&
          transcription == other.transcription &&
          receivedAt == other.receivedAt;
}
